{"content": """"
Health Monitor for Orchestrator System
=======================================

Monitors system health:
- Redis connectivity
- Database health
- Agent health
- Queue health
- System metrics
"""

import time
import redis
import sqlite3
from typing import Dict, Optional
from pathlib import Path

from .config import Config


class HealthStatus:
    """Health status representation."""

    def __init__(self):
        self.healthy = True
        self.checks = {}
        self.timestamp = time.time()

    def add_check(self, name: str, status: bool, message: str = "", details: Optional[Dict] = None):
        """Add health check result."""
        self.checks[name] = {
            "status": "healthy" if status else "unhealthy",
            "message": message,
            "details": details or {}
        }
        if not status:
            self.healthy = False

    def to_dict(self) -> Dict:
        """Convert to dictionary."""
        return {
            "healthy": self.healthy,
            "timestamp": self.timestamp,
            "checks": self.checks
        }


class HealthMonitor:
    """System health monitor."""

    def __init__(self):
        """Initialize health monitor."""
        self.redis_client = None
        self.last_check = None

    def _get_redis(self) -> redis.Redis:
        """Get Redis client."""
        if not self.redis_client:
            self.redis_client = redis.from_url(
                Config.get_redis_url(),
                decode_responses=True
            )
        return self.redis_client

    def check_redis(self) -> tuple[bool, str, Dict]:
        """Check Redis connectivity and health."""
        try:
            r = self._get_redis()

            # Ping test
            r.ping()

            # Get info
            info = r.info()

            details = {
                "version": info.get("redis_version", "unknown"),
                "uptime_seconds": info.get("uptime_in_seconds", 0),
                "connected_clients": info.get("connected_clients", 0),
                "used_memory_human": info.get("used_memory_human", "unknown"),
                "total_commands_processed": info.get("total_commands_processed", 0)
            }

            return True, "Redis is healthy", details

        except redis.ConnectionError as e:
            return False, f"Redis connection failed: {e}", {}
        except Exception as e:
            return False, f"Redis check failed: {e}", {}

    def check_database(self) -> tuple[bool, str, Dict]:
        """Check SQLite database health."""
        try:
            db_path = Config.ORCHESTRATOR_DB

            if not db_path.exists():
                return False, "Database file does not exist", {}

            conn = sqlite3.connect(str(db_path))
            cursor = conn.cursor()

            # Check tables exist
            cursor.execute("SELECT name FROM sqlite_master WHERE type='table'")
            tables = [row[0] for row in cursor.fetchall()]

            expected_tables = ["agents", "agent_activity"]
            missing_tables = [t for t in expected_tables if t not in tables]

            if missing_tables:
                conn.close()
                return False, f"Missing tables: {missing_tables}", {}

            # Get counts
            cursor.execute("SELECT COUNT(*) FROM agents")
            agent_count = cursor.fetchone()[0]

            cursor.execute("SELECT COUNT(*) FROM agent_activity")
            activity_count = cursor.fetchone()[0]

            # Get database size
            db_size = db_path.stat().st_size

            conn.close()

            details = {
                "database_path": str(db_path),
                "database_size_bytes": db_size,
                "tables": tables,
                "agent_count": agent_count,
                "activity_count": activity_count
            }

            return True, "Database is healthy", details

        except sqlite3.Error as e:
            return False, f"Database error: {e}", {}
        except Exception as e:
            return False, f"Database check failed: {e}", {}

    def check_agents(self) -> tuple[bool, str, Dict]:
        """Check agent health."""
        try:
            from .agent_registry import AgentRegistry

            registry = AgentRegistry()
            stats = registry.get_registry_stats()

            # Cleanup offline agents
            cleaned = registry.cleanup_offline_agents()

            details = {
                "total_agents": stats["total_agents"],
                "online_agents": stats["online_agents"],
                "offline_agents": stats["offline_agents"],
                "by_status": stats["by_status"],
                "cleaned_up": cleaned
            }

            # Consider unhealthy if no agents online
            if stats["online_agents"] == 0 and stats["total_agents"] > 0:
                return False, "No agents online", details

            return True, f"{stats['online_agents']} agents online", details

        except Exception as e:
            return False, f"Agent check failed: {e}", {}

    def check_queue(self) -> tuple[bool, str, Dict]:
        """Check task queue health."""
        try:
            from .task_queue import TaskQueue

            queue = TaskQueue()
            stats = queue.get_queue_stats()

            details = {
                "pending_tasks": stats["pending_tasks"],
                "priority_tasks": stats["priority_tasks"],
                "total_tasks": stats["total_tasks"],
                "by_status": stats["tasks_by_status"]
            }

            return True, f"{stats['total_tasks']} tasks in queue", details

        except Exception as e:
            return False, f"Queue check failed: {e}", {}

    def check_system(self) -> tuple[bool, str, Dict]:
        """Check system resources."""
        try:
            import psutil

            # CPU
            cpu_percent = psutil.cpu_percent(interval=0.1)

            # Memory
            memory = psutil.virtual_memory()

            # Disk
            disk = psutil.disk_usage('/')

            details = {
                "cpu_percent": cpu_percent,
                "memory_percent": memory.percent,
                "memory_available_mb": memory.available / (1024 * 1024),
                "disk_percent": disk.percent,
                "disk_free_gb": disk.free / (1024 * 1024 * 1024)
            }

            # Warning thresholds
            warnings = []
            if cpu_percent > 90:
                warnings.append("High CPU usage")
            if memory.percent > 90:
                warnings.append("High memory usage")
            if disk.percent > 90:
                warnings.append("Low disk space")

            if warnings:
                return False, f"System issues: {', '.join(warnings)}", details

            return True, "System resources healthy", details

        except ImportError:
            # psutil not installed, skip system check
            return True, "System check skipped (psutil not installed)", {}
        except Exception as e:
            return False, f"System check failed: {e}", {}

    def health_check(self) -> HealthStatus:
        """
        Perform comprehensive health check.

        Returns:
            HealthStatus object
        """
        status = HealthStatus()

        # Redis check
        redis_ok, redis_msg, redis_details = self.check_redis()
        status.add_check("redis", redis_ok, redis_msg, redis_details)

        # Database check
        db_ok, db_msg, db_details = self.check_database()
        status.add_check("database", db_ok, db_msg, db_details)

        # Agent check
        agent_ok, agent_msg, agent_details = self.check_agents()
        status.add_check("agents", agent_ok, agent_msg, agent_details)

        # Queue check
        queue_ok, queue_msg, queue_details = self.check_queue()
        status.add_check("queue", queue_ok, queue_msg, queue_details)

        # System check
        system_ok, system_msg, system_details = self.check_system()
        status.add_check("system", system_ok, system_msg, system_details)

        self.last_check = status
        return status

    def is_healthy(self) -> bool:
        """Quick health check."""
        try:
            # Just check Redis and DB
            redis_ok, _, _ = self.check_redis()
            db_ok, _, _ = self.check_database()
            return redis_ok and db_ok
        except:
            return False
